"""Load station readings and summarize them."""

from __future__ import annotations

import csv
from datetime import date


def load_rows(path: str) -> list[dict]:
    """Read a station CSV into readings sorted by day."""
    rows = []
    with open(path, newline="", encoding="utf-8") as handle:
        for raw in csv.DictReader(handle):
            rows.append(
                {
                    "day": date.fromisoformat(raw["date"]),
                    "temp_c": float(raw["temp_c"]),
                    "rain_mm": float(raw["rain_mm"]),
                    "wind_kph": float(raw["wind_kph"]),
                }
            )
    return sorted(rows, key=lambda row: row["day"])


def daily_summary(rows: list[dict]) -> dict:
    """Day count, temperature range and mean, and total rain."""
    temps = [row["temp_c"] for row in rows]
    return {
        "days": len(rows),
        "temp_min": min(temps),
        "temp_max": max(temps),
        "temp_mean": round(sum(temps) / len(temps), 1),
        "rain_total": round(sum(row["rain_mm"] for row in rows), 1),
    }


def to_fahrenheit(celsius: float) -> float:
    """Convert Celsius to Fahrenheit, rounded to one decimal place."""
    return round(celsius * 9 / 5 + 32, 1)

