"""Plain-text report for one station CSV file."""

from __future__ import annotations

import sys

from weather.summary import daily_summary, load_rows

LABELS = {
    "days": "Days",
    "temp_min": "Min temp (C)",
    "temp_max": "Max temp (C)",
    "temp_mean": "Mean temp (C)",
    "rain_total": "Total rain (mm)",
}


def format_report(summary: dict) -> str:
    """An aligned table: labels on the left, values right-aligned."""
    width = max(len(label) for label in LABELS.values())
    return "\n".join(
        f"{LABELS[key]:<{width}}  {value:>8}" for key, value in summary.items()
    )


def main(argv: list[str]) -> int:
    """Print the report for the station CSV file given as the first argument."""
    print(format_report(daily_summary(load_rows(argv[1]))))
    return 0


if __name__ == "__main__":
    raise SystemExit(main(sys.argv))

